board-lane-rects.code:
const gap = count > 4 ? 0.8 : 1.6;
const h = (area.h - gap * (count - 1)) / count;
return Array.from({ length: count }, (_, i) => ({ x: area.x, y: area.y + i * (h + gap), w: area.w, h }));

board-scheduler-moves.code:
const moves: Move[] = [];
for (const p of frame.processes) {
  const before = previous.processes.find((q) => q.pid === p.pid)?.core ?? null;
  if (before !== p.core) moves.push({ program: p.name, from: before, to: p.core });
}
return moves;

board-interrupt-markers.code:
const raised: InterruptMarker[] = frame.packets
  .filter((p) => p.type === "irq" && p.address !== null)
  .map((p) => ({ kind: "raised", from: p.from, vector: p.address ?? 0 }));
const wasInHandler = (id: number) => previous?.cores.find((c) => c.id === id)?.inHandler ?? false;
const taken: InterruptMarker[] = frame.cores
  .filter((c) => c.inHandler && !wasInHandler(c.id))
  .map((c) => ({ kind: "taken", core: c.id, vector: handlerOf(c.pc) }));
return [...raised, ...taken];

board-draw-cores.code:
const lanes = laneRects(frame.cores.length, { x: rect.x, y: rect.y + 6, w: rect.w, h: rect.h - 14 });
const moves = previous ? schedulerMoves(previous, frame) : [];
const markers = interruptMarkers(previous, frame);
const notes = [
  ...moves.map((m) => (m.to === null ? `${m.program} leaves core ${m.from}` : m.from === null ? `${m.program} -> core ${m.to}` : `${m.program}: core ${m.from} -> ${m.to}`)),
  ...markers.map((m) =>
    m.kind === "raised" ? `⚡ ${frame.parts[m.from]?.label ?? m.from} interrupts (handler ${hex(m.vector)})` : `⚡ core ${m.core} runs the handler at ${hex(m.vector)}`,
  ),
  ...(frame.pendingIrqs > 0 ? [`${frame.pendingIrqs} ${frame.pendingIrqs === 1 ? "interrupt waits" : "interrupts wait"} for a core`] : []),
];
return (
  <g>
    <Label x={rect.x} y={rect.y + 2} anchor="start" size={12} weight={700}>
      {`CPU · ${frame.cores.length} cores`}
    </Label>
    {frame.cores.map((core, i) => (
      <CoreView key={core.id} frame={frame} core={core} rect={lanes[i]} colour={coreColour(core.id)} />
    ))}
    <Label x={rect.x} y={rect.y + rect.h - 3} anchor="start" size={11} weight={600} fill={notes.length ? INK.red : INK.darkGrey}>
      {notes.length ? notes.join("  ·  ") : "scheduler: no changes this tick"}
    </Label>
  </g>
);

timer-tick.code:
if (state.fsm !== "COUNTING") return { state, effects: [] };
const elapsed = state.elapsed + 1;
if (elapsed < state.interval) return { state: { ...state, elapsed }, effects: [] };
return { state: { ...state, elapsed: 0, count: state.count + 1 }, effects: [{ kind: "irq" }] };

enter-interrupt.code:
if (!canTakeInterrupt(core)) throw new Error(`core ${core.id} can't take an interrupt in ${core.phase}`);
const resume = core.phase === "IDLE" ? "IDLE" : "FETCH";
const frame = { registers: core.registers, pc: core.pc, flags: core.flags, retired: core.retired, resume } as const;
return { ...core, stack: [frame], pc: vector, phase: coreFsm.go(core.phase, "FETCH") };

iret.code:
const [frame] = core.stack;
if (!frame) return faultWith(core, "IRET outside an interrupt handler");
return {
  core: {
    ...moveTo(core, frame.resume),
    registers: frame.registers,
    pc: frame.pc,
    flags: frame.flags,
    stack: [],
    retired: frame.retired,
  },
  effects: [],
};
